class Solution:
    def smallestNegatedPermutation(self, n: int, target: int) -> List[int]:
        S = n * (n + 1) // 2
        if abs(target) > S or (S - target) % 2:
            return []
        rem = (S - target) // 2
        negated = set()
        for v in range(n, 0, -1):
            if rem >= v:
                negated.add(v)
                rem -= v
        return ([-v for v in sorted(negated, reverse=True)]
                + [v for v in range(1, n + 1) if v not in negated])

