class Solution {
public:
    vector<long long> smallestNegatedPermutation(int n, long long target) {
        long long S = 1LL * n * (n + 1) / 2;
        vector<long long> res;
        if (llabs(target) > S || (S - target) % 2) return res;
        long long rem = (S - target) / 2;
        vector<char> neg(n + 1, 0);
        for (int v = n; v >= 1; v--)
            if (rem >= v) { neg[v] = 1; rem -= v; }
        for (int v = n; v >= 1; v--) if (neg[v]) res.push_back(-v);
        for (int v = 1; v <= n; v++) if (!neg[v]) res.push_back(v);
        return res;
    }
};

