class Solution {
    public long[] smallestNegatedPermutation(int n, long target) {
        long S = (long) n * (n + 1) / 2;
        if (Math.abs(target) > S || (S - target) % 2 != 0) return new long[0];
        long rem = (S - target) / 2;
        boolean[] neg = new boolean[n + 1];
        for (int v = n; v >= 1; v--)
            if (rem >= v) { neg[v] = true; rem -= v; }
        long[] res = new long[n]; int i = 0;
        for (int v = n; v >= 1; v--) if (neg[v]) res[i++] = -v;
        for (int v = 1; v <= n; v++) if (!neg[v]) res[i++] = v;
        return res;
    }
}

