var smallestNegatedPermutation = function(n, target) {
    const S = n * (n + 1) / 2;
    if (Math.abs(target) > S || (S - target) % 2 !== 0) return [];
    let rem = (S - target) / 2;
    const neg = new Array(n + 1).fill(false);
    for (let v = n; v >= 1; v--)
        if (rem >= v) { neg[v] = true; rem -= v; }
    const res = [];
    for (let v = n; v >= 1; v--) if (neg[v]) res.push(-v);
    for (let v = 1; v <= n; v++) if (!neg[v]) res.push(v);
    return res;
};
